/* Accessible range selection over the existing native date inputs.
   Only the existing form submit commits dates; close/Escape discard the draft. */
(()=>{'use strict';const dialog=document.querySelector('#dates-dialog'),form=document.querySelector('#dates-form');if(!dialog||!form)return;
const start=form.elements.checkin,end=form.elements.checkout,mobile=matchMedia('(max-width:767px)');
const date=s=>new Date(s+'T12:00:00Z'),iso=d=>d.toISOString().slice(0,10),add=(s,n)=>{const d=date(s);d.setUTCDate(d.getUTCDate()+n);return iso(d);},month=(s,n=0)=>{const d=date(s);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);return iso(d);};
const full=s=>date(s).toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'});
let shown='',choosingEnd=false;
const calendar=document.createElement('div');calendar.className='range-calendar';calendar.innerHTML='<div class="calendar-toolbar"><button type="button" data-month-prev aria-label="Предыдущий месяц">←</button><span class="calendar-hint" aria-live="polite"></span><button type="button" data-month-next aria-label="Следующий месяц">→</button></div><div class="calendar-months"></div><p class="calendar-summary" aria-live="polite"></p>';
form.querySelector('.date-grid').after(calendar);const months=calendar.querySelector('.calendar-months'),hint=calendar.querySelector('.calendar-hint'),summary=calendar.querySelector('.calendar-summary');
function render(focusDate){if(!shown)return;hint.textContent=choosingEnd?'Выберите дату выезда':'Выберите дату заезда';summary.textContent=start.value&&end.value?full(start.value)+' — '+full(end.value)+' · '+Math.round((date(end.value)-date(start.value))/86400000)+' '+plural(Math.round((date(end.value)-date(start.value))/86400000)):'Можно выбрать дни в календаре или ввести даты в полях выше.';calendar.querySelector('[data-month-prev]').disabled=shown<=month(start.min);months.replaceChildren();
 for(let offset=0;offset<(mobile.matches?1:2);offset++){const first=month(shown,offset),d=date(first),section=document.createElement('section');section.className='calendar-month';const title=document.createElement('h3');title.textContent=d.toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'});section.append(title);const grid=document.createElement('div');grid.className='calendar-grid';grid.setAttribute('role','group');grid.setAttribute('aria-label',title.textContent);['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].forEach(day=>{const label=document.createElement('span');label.className='weekday';label.textContent=day;label.setAttribute('aria-hidden','true');grid.append(label);});const empty=(d.getUTCDay()+6)%7;for(let n=0;n<empty;n++)grid.append(document.createElement('span'));
 const length=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();for(let day=1;day<=length;day++){const value=add(first,day-1),b=document.createElement('button');b.type='button';b.className='calendar-day';b.dataset.date=value;b.textContent=day;const chosen=value===start.value||value===end.value;b.classList.toggle('chosen',chosen);b.classList.toggle('in-range',!!start.value&&!!end.value&&value>start.value&&value<end.value);b.classList.toggle('today',value===start.min);b.disabled=value<start.min||(choosingEnd&&value<=start.value);b.setAttribute('aria-pressed',String(chosen));b.setAttribute('aria-label',full(value)+(value===start.min?', сегодня':'')+(value===start.value?', заезд':value===end.value?', выезд':''));b.tabIndex=-1;grid.append(b);}section.append(grid);months.append(section);}
 const target=months.querySelector('[data-date="'+(focusDate||start.value||start.min)+'"]:not(:disabled)')||months.querySelector('button:not(:disabled)');if(target){target.tabIndex=0;if(focusDate)target.focus({preventScroll:true});}
}
function plural(n){return n%10===1&&n%100!==11?'ночь':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'ночи':'ночей';}
calendar.addEventListener('click',ev=>{const day=ev.target.closest('[data-date]');if(day){if(!choosingEnd){start.value=day.dataset.date;end.value='';end.min=add(start.value,1);choosingEnd=true;render(add(start.value,1));}else{end.value=day.dataset.date;choosingEnd=false;render(day.dataset.date);}form.querySelector('.form-error').textContent='';}if(ev.target.closest('[data-month-prev],[data-month-next]')){shown=month(shown,ev.target.closest('[data-month-prev]')?-1:1);render();}});
months.addEventListener('keydown',ev=>{const b=ev.target.closest('[data-date]');if(!b)return;const moves={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};let next;if(ev.key in moves)next=add(b.dataset.date,moves[ev.key]);else if(ev.key==='Home')next=add(b.dataset.date,-((date(b.dataset.date).getUTCDay()+6)%7));else if(ev.key==='End')next=add(b.dataset.date,6-((date(b.dataset.date).getUTCDay()+6)%7));else if(ev.key==='PageUp'||ev.key==='PageDown')next=month(b.dataset.date,ev.key==='PageUp'?-1:1);else return;ev.preventDefault();if(next<(choosingEnd?end.min:start.min))next=choosingEnd?end.min:start.min;if(next<shown||next>=month(shown,mobile.matches?1:2))shown=month(next);render(next);});
start.addEventListener('change',()=>{if(start.value){shown=month(start.value);choosingEnd=true;render();}});end.addEventListener('change',()=>{choosingEnd=false;render();});
new MutationObserver(()=>{if(dialog.open){shown=month(start.value||start.min);choosingEnd=false;render();}}).observe(dialog,{attributes:true,attributeFilter:['open']});mobile.addEventListener('change',()=>{if(dialog.open)render();});
})();
